  'ο': 'o', 'α': 'a', 'ε': 'e', 'ι': 'i', 'ρ': 'p', 'ν': 'v', 'τ': 't', 'κ': 'k', 'Ο': 'O', 'Α': 'A', 'Ε': 'E', 'Ι': 'I', 'Ρ': 'P', 'Τ': 'T', 'Κ': 'K', 'Ν': 'N' };
