const skeleton = (t) => visible(t).normalize('NFKC').replace(/[Ͱ-ϿЀ-ӿԀ-ԯɡգ-օ]/g, (c) => CONFUSABLE[c] || c);
const looksInjected = (t) => INJECTION.test(skeleton(t));
// cut injected sentences; also break the prompt's own markers so an ad cannot fake a "### JOB" block or "Notes:" line
function aiSafe(t) {
  return visible(t)
    .replace(/[^.!?\n]+[.!?]*/g, (s) => (INJECTION.test(skeleton(s)) ? ' [text addressed to the AI removed]' : s))
    .replace(/#{2,}/g, '#').replace(/^\s*(notes|ad text|title|company|location)\s*:/gim, '$1 -');
}
const rc = CFG.recheck || {};
const first = ($('Gemini Results').first().json.results || []).filter((r) => r.fit_score >= (rc.minScore || 65))
  .sort((a, b) => b.fit_score - a.fit_score).slice(0, rc.maxJobs || 15);
if (!first.length) return [{ json: { nothing: true } }];
const squeeze = (t) => String(t || '').replace(/[ \t]+/g, ' ').replace(/\s*\n\s*/g, '\n');
const details = $('Get Job Details').all().map((i) => i.json);
// the job blocks Make Batches wrote for the first pass, with the ad text swapped for a longer version
const blocks = {};
for (const { json: b } of $('Make Batches').all()) {
  for (const part of String(b.jobsText || '').split(/\n\n(?=### JOB )/)) {
    const id = (part.match(/^### JOB (J\d+)/) || [])[1];
    const full = id && aiSafe(squeeze((details[Number(id.slice(1)) - 1] || {}).description).slice(0, 4000));
    if (id) blocks[id] = full ? part.replace(/\nAd text: [\s\S]*?\nNotes: /, () => `\nAd text: ${full}\nNotes: `) : part;
  }
}
const base = $('Make Batches').first().json;
const size = Math.max(1, rc.jobsPerCall || 5);
const out = [];
for (let i = 0; i < first.length; i += size) {
  const ids = first.slice(i, i + size).map((r) => r.id).filter((id) => blocks[id]);
  if (ids.length) out.push({ json: { resume: base.resume, about: base.about, jobsText: ids.map((id) => blocks[id]).join('\n\n'), ids } });
}
return out.length ? out : [{ json: { nothing: true } }];

// Stronger model's answers -> scores (same rules as the first pass, lib/score-v2.js). Build Rows prefers these.
// v2 scoring rules, inlined into Local Results and Gemini Results by build-workflows.js.
// The AI scores four rubric parts; the fit score is their sum, computed here, capped when a hard blocker applies.
// A blocker the AI claims only counts if its quote is really in the job's title/ad. Location of non-remote jobs is
// left to the code (the AI tends to quote the job's own city as a "blocker"). Blockers the code found always apply.
const BLOCKERS = ['language', 'location', 'eligibility', 'seniority', 'profession'];
const PARTS = { skills: 40, experience: 25, domain: 15, must_haves: 20 };
const BLOCKED_MAX = 45;
const NO_EVIDENCE_MAX = 60; // nothing in MY RESUME matches the ad: at most "maybe", never "apply"
const LANGUAGE_RISK_MAX = 69; // local language likely needed but not proven (job.langRisk from Make Batches): at most "maybe"
const noEvidence = (s) => /^\s*(none|n\/a)?\W*$/i.test(String(s ?? ''));
const words = (s) => String(s || '').toLowerCase().match(/[\p{L}\p{N}]+/gu) || [];
function quoteFound(quote, job, blocker) {
  const q = words(quote).filter((w) => w.length > 2);
  if (!q.length || /^none$/i.test(String(quote || '').trim())) return false;
  const have = new Set(words(blocker === 'location' ? job.ad : job.title + ' ' + job.ad));
  return q.filter((w) => have.has(w)).length / q.length >= 0.8;
}
// raw = one job from the AI's answer; job = { id, title, ad, remote, langRisk, blockers } from Make Batches
function finish(raw, job) {
  const parts = Object.fromEntries(Object.entries(PARTS).map(([k, max]) => [k, Math.max(0, Math.min(max, Math.round(Number(raw[k]) || 0)))]));
  const claimed = [...new Set((raw.blockers || []).filter((b) => BLOCKERS.includes(b)))];
  const kept = claimed.filter((b) => (b !== 'location' || job.remote) && quoteFound(raw.blocker_quote, job, b));
  const blockers = [...new Set([...kept, ...job.blockers])];
  const sum = Object.values(parts).reduce((a, b) => a + b, 0);
  // soft caps (not blockers): the job can still show up as "maybe"
  const caps = [noEvidence(raw.evidence) && NO_EVIDENCE_MAX, job.langRisk && LANGUAGE_RISK_MAX, blockers.length && BLOCKED_MAX].filter(Boolean);
  return { id: job.id, fit_score: Math.min(sum, ...caps), parts, blockers,
    why: raw.why, gaps: raw.gaps, resume_changes: raw.resume_changes, visa_note: raw.visa_note, language_note: raw.language_note };
}
// several answers for the same job -> the one with the median score (so its why/gaps match the score)
function median(answers) {
  const xs = [...answers].sort((a, b) => a.fit_score - b.fit_score);
  return { ...xs[(xs.length - 1) >> 1], samples: xs.map((x) => x.fit_score) };
}
// job info by id, from the Make Batches items
const jobsById = () => Object.fromEntries($('Make Batches').all().flatMap((i) => i.json.jobs || []).map((j) => [j.id, j]));
const byJob = jobsById();
const results = $input.all().flatMap((i) => ((i.json.output || {}).results || []))
  .map((raw) => [raw, byJob[String((raw && raw.id) || '').trim().toUpperCase()]]).filter(([, job]) => job).map(([raw, job]) => finish(raw, job));
return [{ json: { results } }];

// Merge AI scores with the job data into one row per job.
const c = $('Config').first().json;
const jobs = $('Get Job Details').all().map((i, n) => ({ ...i.json, n: n + 1 }));
const vr = $('Visa & Rates').first().json;
const fx = vr.fx || null;
const ai = {}, rechecked = new Set();
// first scores from Gemini Flash-Lite, then the stronger model's second check of the best jobs (it wins)
for (const node of ['Gemini Results', 'Recheck Results']) {
  let items = [];
  try { items = $(node).all(); } catch (e) { /* this node did not run this time */ }
  for (const it of items) for (const r of (it.json.results || [])) if (r && r.id) {
    const id = String(r.id).trim().toUpperCase();
    ai[id] = r;
    if (node === 'Recheck Results') rechecked.add(id);
  }
}
// recruitment agencies: the sponsor list shows the agency, not the real employer
const AGENCY = /\b(recruit\w*|staffing|personnel|resourcing|talent solutions|headhunt\w*|michael page|page personnel|hays|robert half|robert walters|randstad|adecco|manpower|reed|harvey nash|sthree|computer futures|progressive recruitment|hamilton barnes|matchtech|tekwissen|datatech|optimum|ferchau|persona service|brunel|gulp|etengo|amadeus fire|experis|modis|akkodis|allegis|aerotek|kforce|tempton|orizon|hofmann|dis ag|jobvalley|academic work|nigel frank|jefferson frank|cpl|morgan mckinley|huxley|spring professional)\b/i;
const SHORT_AD = 400;   // Careerjet and some boards only give a snippet
const SUSPICIOUS_MAX = 50;

const CUR = { Germany: 'EUR', Netherlands: 'EUR', Austria: 'EUR', Ireland: 'EUR', UK: 'GBP', Sweden: 'SEK', India: 'INR', UAE: 'AED' };
const SYM = { EUR: '€', INR: '₹', USD: '$', GBP: '£', AED: 'AED ', SEK: 'SEK ' };
const YEAR = { year: 1, month: 12, week: 52, day: 220, hour: 1760 };
const CUR2 = c.currency2 || 'GBP';   // the second salary column (for example GBP or INR)
const k = (v) => (v >= 1000 ? Math.round(v / 1000) + 'k' : String(Math.round(v)));
// rupees read naturally in lakh: ₹12.5L
const amount = (cur, v) => (cur === 'INR' ? `${Math.round(v / 10000) / 10}L` : k(v));
function salary(s, country) {
  if (!s || !(s.min || s.max)) return ['', '', ''];
  const cur = (s.cur || CUR[s.country || country] || 'EUR').toUpperCase();
  const lo = s.min || s.max, hi = s.max || s.min, f = YEAR[s.per] || 1;
  const given = `${SYM[cur] || cur + ' '}${Math.round(lo).toLocaleString('en')}${hi !== lo ? '–' + Math.round(hi).toLocaleString('en') : ''} / ${s.per || 'year'}`;
  if (!fx || !fx[cur]) return [given, '', ''];
  const eLo = (lo * f) / fx[cur], eHi = (hi * f) / fx[cur];
  const eur = `€${k(eLo)}${eHi !== eLo ? '–' + k(eHi) : ''}`;
  const sym2 = SYM[CUR2] || CUR2 + ' ';
  const second = fx[CUR2] ? `${sym2}${amount(CUR2, eLo * fx[CUR2])}${eHi !== eLo ? '–' + amount(CUR2, eHi * fx[CUR2]) : ''}` : '';
  return [given, eur, second];
}
// Drop "Add '...'" suggestions that quote things not in the CV (the model sometimes invents skills).
const squash = (s) => String(s || '').toLowerCase().replace(/[^\p{L}\p{N}]/gu, '');
const cvText = squash(($('Get Master Resume').first().json || {}).content);
function truthful(s) {
  if (!/^\s*add\b/i.test(s)) return true;
  const parts = [...s.matchAll(/['‘’"“”]([^'‘’"“”]+)['‘’"“”]/g)].flatMap((m) => m[1].split(/,|\(|\)|\band\b|&|\//)).map((t) => t.trim()).filter((t) => t.length > 2);
  return parts.length > 0 && parts.every((p) => cvText.includes(squash(p)));
}
const today = $now.toFormat('yyyy-MM-dd');
const rows = jobs.map((j) => {
  const r = ai['J' + j.n] || null;
  const raw = r && Number.isFinite(Number(r.fit_score)) ? Math.max(0, Math.min(100, Math.round(Number(r.fit_score)))) : 0;
  // an ad that tried to talk to the AI cannot buy itself a top score
  const fit = j.suspicious ? Math.min(raw, SUSPICIOUS_MAX) : raw;
  const [sal, eur, second] = salary(j.salary, j.country);
  const agency = AGENCY.test(j.company);
  const adNote = r && r.visa_note && !/not mentioned/i.test(r.visa_note) ? r.visa_note : '';
  const visa = agency && ['UK', 'Netherlands'].includes(j.country) ? 'Agency – check who the employer is' + (adNote ? ' · Ad: ' + adNote : '')
    : (vr.sponsors && vr.sponsors[j.id]) ? vr.sponsors[j.id] + (adNote ? ' · Ad: ' + adNote : '')
    : (r && r.visa_note) || '';
  const shortAd = (j.description || '').length < SHORT_AD;
  const flags = [j.suspicious && 'Odd ad text aimed at AI tools – treat with care', shortAd && 'Short ad – read the full ad before applying',
    agency && 'Recruitment agency – find out the real employer', rechecked.has('J' + j.n) && 'Double-checked by stronger AI'].filter(Boolean);
  return { ...j, fit, today, scored: Boolean(r),
    verdict: fit >= 75 ? 'Strong' : fit >= 55 ? 'Good' : fit >= 40 ? 'Possible' : 'Weak',
    why: r ? String(r.why || '').trim() : '', gaps: r ? String(r.gaps || '').trim() : '',
    resumeChanges: r ? String(r.resume_changes || '').split(/\s*\|\s*/).filter(Boolean).filter(truthful).map((s) => '• ' + s).join('\n') : '',
    visa, language: r ? String(r.language_note || '').trim() : '', salaryText: sal, salaryEur: eur, salary2: second, shortAd, agency, flags,
    keep: Boolean(r) && !j.skipReason && fit >= c.minFitScoreToLog,
    note: j.skipReason || (r ? `${j.company} – ${j.title}` : `Not scored (AI unavailable) – ${j.company} – ${j.title}`) };
}).sort((a, b) => b.fit - a.fit);
return rows.map((r) => ({ json: r }));

// Map kept jobs to the Jobs tab columns.
return $input.all().map((i) => i.json).filter((r) => r.keep).map((r) => ({ json: {
  'Date Found': r.today, 'Fit Score': r.fit, 'Verdict': r.verdict, 'Role': r.title, 'Company': r.company, 'Country': r.country,
  'Location': r.location, 'Work Mode': r.workMode, 'Visa / Sponsor': r.visa, 'Language': r.language,
  'Salary': r.salaryText, 'Salary (EUR/yr)': r.salaryEur, ["Salary (GBP/yr)"]: r.salary2,
  'Why It Fits': r.why, 'Gaps': r.gaps, 'Resume Changes': r.resumeChanges, 'Job Link': r.link, 'More Links': r.moreLinks,
  'Source': r.source, 'Posted': r.posted, 'Status': 'To apply', 'Applied On': '', 'Follow-up': '', 'Notes': r.flags.join(' · '),
} }));

// Low scores and skipped jobs go to Seen. Unscored jobs (AI error) are left out so the next run retries them.
return $input.all().map((i) => i.json).filter((r) => !r.keep && (r.skipReason || r.scored)).map((r) => ({ json: {
  'Job Link': r.link, 'Date': r.today, 'Fit Score': r.skipReason ? '' : r.fit, 'Note': r.note, 'Key': r.key,
} }));

// Daily job email (n8n Code node "Digest Email"). Greeting, footer and visa line come from the profile's Config.
// All new jobs, best match first, max 25, an "Apply today" top 5 (rolls over 14 days) and follow-up reminders. Always sends something, so they know it ran.
const c = $('Config').first().json;
if (!c.digestEmail) return [];
// job text comes from job boards and the sheet (which people edit): escape everything, quotes too, and only link to http(s)
const esc = (s) => String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
const href = (u) => (/^https?:\/\/[^\s"'<>]+$/i.test(String(u || '').trim()) ? esc(String(u).trim()) : '#');
const hi = (s) => (c.emailGreeting ? c.emailGreeting + s.charAt(0).toLowerCase() + s.slice(1) : s);
const VISA_COUNTRY = { uk: 'UK', nl: 'Netherlands' };
const visaCountries = (c.visaChecks || []).map((v) => VISA_COUNTRY[v]).filter(Boolean);
const rows = $input.all().map((i) => i.json).filter((r) => r && r.link);
const jobs = rows.filter((r) => r.keep).sort((a, b) => b.fit - a.fit);
const shown = jobs.slice(0, 25);
const notScored = rows.filter((r) => !r.scored && !r.skipReason).length;   // AI busy: these are tried again tomorrow
const day = $now.toFormat('cccc d LLLL');
const sheetUrl = 'https://docs.google.com/spreadsheets/d/__SHEET_ID__/edit';
// applied 7+ days ago, flagged "Due" by the daily sheet check
const followUps = $('Get Jobs Already Logged').all().map((i) => i.json).filter((r) => r && r.Status === 'Applied' && /^due/i.test(String(r['Follow-up'] || '')));
const followHtml = followUps.length ? `<h3 style="margin:18px 0 6px">Time to follow up</h3><p style="font-size:13px;margin:0 0 6px">You applied 7+ days ago - a short, friendly email to the company can help.</p>
  <ul>${followUps.map((r) => `<li><a href="${href(r['Job Link'])}">${esc(r.Role)}</a> - ${esc(r.Company)} (applied ${esc(r['Applied On'])})</li>`).join('')}</ul>
  <p style="font-size:12px;color:#5f6368">After following up, set "Follow-up" to Done in your job list.</p>` : '';
const color = (f) => (f >= 75 ? '#1e8e3e' : f >= 55 ? '#188038' : '#b06000');
const card = (r) => `
  <div style="border:1px solid #e0e0e0;border-radius:10px;padding:14px 16px;margin:0 0 12px">
    <div style="font-size:17px;font-weight:600">${esc(r.title)}</div>
    <div style="font-size:14px;color:#3c4043;margin:2px 0 6px">${esc(r.company)} · ${esc(r.location || r.country)}${r.workMode ? ' · ' + esc(r.workMode) : ''}</div>
    <div style="font-size:14px"><b style="color:${color(r.fit)}">Match ${Number(r.fit) || 0}/100 (${esc(r.verdict)})</b></div>
    ${(r.flags || []).length ? `<div style="font-size:12px;margin-top:4px;color:#b06000">${r.flags.map(esc).join(' · ')}</div>` : ''}
    ${r.why ? `<div style="font-size:13px;margin-top:6px">${esc(r.why)}</div>` : ''}
    ${r.salaryText ? `<div style="font-size:13px;margin-top:4px"><b>Salary:</b> ${esc(r.salaryText)}${r.salary2 ? ` (≈ ${esc(r.salary2)} per year)` : ''}</div>` : ''}
    ${visaCountries.includes(r.country) && r.visa ? `<div style="font-size:13px;margin-top:4px"><b>Visa:</b> ${esc(r.visa)}</div>` : ''}
    ${r.language && !/not mentioned|english only/i.test(r.language) ? `<div style="font-size:13px;margin-top:4px"><b>Language:</b> ${esc(r.language)}</div>` : ''}
    ${r.resumeChanges ? `<div style="font-size:13px;margin-top:6px"><b>Tip for your CV:</b><br>${esc(r.resumeChanges).replace(/\n/g, '<br>')}</div>` : ''}
    <div style="margin-top:10px"><a href="${href(r.link)}" style="background:#1a73e8;color:#fff;padding:8px 16px;border-radius:6px;text-decoration:none;font-size:14px">Apply</a></div>
  </div>`;
let subject, body;
if (shown.length) {
  subject = `Your job list for ${day}: ${jobs.length} new job${jobs.length === 1 ? '' : 's'}`;
  body = `<p>${hi('Here are today\'s new jobs, best match first. Click <b>Apply</b> to open the job.')}</p>
  ${shown.map(card).join('')}
  ${jobs.length > shown.length ? `<p style="color:#5f6368">…and ${jobs.length - shown.length} more with a lower match (not shown).</p>` : ''}`;
} else if (notScored) {
  subject = `Your job list for ${day} is delayed`;
  body = `<p>${hi('Today\'s jobs could not be checked yet (the AI was busy). They will be in tomorrow\'s email.')}</p>`;
} else {
  subject = `No new jobs today (${day})`;
  body = `<p>${hi('No new matching jobs today. The next list comes tomorrow morning.')}</p>`;
}
// "Apply today": best 5 not-yet-applied jobs from today plus the last 14 days (Status still "To apply")
const since = $now.minus({ days: 14 }).toFormat('yyyy-MM-dd');
const earlier = $('Get Jobs Already Logged').all().map((i) => i.json)
  .filter((r) => r && r['Job Link'] && (r.Status || 'To apply') === 'To apply' && String(r['Date Found'] || '') >= since)
  .map((r) => ({ title: r.Role, company: r.Company, country: r.Country, fit: Number(r['Fit Score']) || 0, link: r['Job Link'], visa: r['Visa / Sponsor'], found: r['Date Found'],
    shortAd: /Short ad/.test(r.Notes || '') }));
// jobs scored from a full ad first: a snippet-only score is a guess, so those only fill up the remaining places
const top = [...jobs, ...earlier].filter((r, i, all) => all.findIndex((x) => x.link === r.link) === i)
  .sort((a, b) => Number(Boolean(a.shortAd)) - Number(Boolean(b.shortAd)) || b.fit - a.fit).slice(0, 5);
const topHtml = top.length ? `<div style="background:#e8f0fe;border-radius:10px;padding:12px 16px;margin:0 0 16px">
  <div style="font-size:16px;font-weight:600;margin-bottom:6px">Apply today: your top ${top.length}</div>
  <ol style="margin:0;padding-left:20px">${top.map((r) => `<li style="margin:4px 0;font-size:14px"><a href="${href(r.link)}">${esc(r.title)}</a> - ${esc(r.company)} (${esc(r.country)}) · <b style="color:${color(r.fit)}">${Number(r.fit) || 0}</b>${r.found ? ` <span style="color:#5f6368;font-size:12px">· from ${esc(r.found)}</span>` : ''}${visaCountries.includes(r.country) && /^Yes/.test(r.visa || '') ? ' <span style="color:#1e8e3e;font-size:12px">· sponsor</span>' : ''}${r.shortAd ? ' <span style="color:#b06000;font-size:12px">· short ad</span>' : ''}</li>`).join('')}</ol>
  <div style="font-size:12px;color:#5f6368;margin-top:6px">Jobs you don't apply to stay here until a better one comes or 14 days pass. Set Status to "Applied" or "Not for me" in the sheet to take one off.</div></div>` : '';
// first thing in the email: mark applications in the sheet (follow-up reminders and the weekly numbers depend on it)
const marked = $('Get Jobs Already Logged').all().map((i) => i.json).filter((r) => r && ['Applied', 'Interview', 'Offer', 'Rejected'].includes(r.Status)).length;
const markHtml = `<div style="border:2px solid #f9ab00;background:#fef7e0;border-radius:10px;padding:12px 16px;margin:0 0 16px">
  <div style="font-size:15px;font-weight:600">${marked ? `${marked} application${marked > 1 ? 's' : ''} marked so far. Applied to more?` : 'Applied to any jobs? Your sheet shows none yet.'}</div>
  <div style="font-size:13px;margin-top:4px">Open <a href="${sheetUrl}">your job list</a>, find the job (also ones from earlier emails) and set its <b>Status</b> to <b>Applied</b>. Then you get a follow-up reminder after 7 days. Interview or offer? Set that Status too.</div></div>`;
const tracker = `<p style="font-size:13px;margin-top:16px"><b>Your job list:</b> <a href="${sheetUrl}">open the sheet</a> - after applying, set the job's Status to "Applied". It reminds you to follow up after 7 days.</p>`;
const html = `<div style="font-family:Arial,sans-serif;max-width:640px">${markHtml}${topHtml}${body}${followHtml}${tracker}
  <p style="font-size:12px;color:#5f6368;margin-top:18px">${esc(c.emailFooter || 'Sent every morning by your job finder.')}</p></div>`;
return [{ json: { to: c.digestEmail, subject, html } }];
